({
  summarize: async (resource) => {
    const fs = require("node:fs");
    const path = require("node:path");
    const content = fs.readFileSync(resource.path, "utf8").slice(0, 3000);
    const projects = await mcode.api.call("project.list", {});
    const matches = (projects.projects || []).filter(p =>
      typeof p.path === "string" && p.path.toLowerCase() === resource.projectPath.toLowerCase());
    if (matches.length !== 1) throw Error("找不到唯一的当前项目，已拒绝跨项目发送摘要");
    const created = await mcode.api.call("claude.startSession", {
      projectId: matches[0].id, title: "文件摘要：" + path.basename(resource.path),
      kind: "chat", effort: "default", permissionMode: "default"
    });
    if (!created.session || typeof created.session.id !== "string") throw Error("未能创建 AI 会话");
    await mcode.api.call("claude.sendTurn", {
      sessionId: created.session.id,
      prompt: "请总结文件 " + path.basename(resource.path) + " 的内容，并列出要点。\n\n" + content
    });
    return { sessionId: created.session.id, sent: true };
  }
})
